<?php
function acAdmin(?array $u):bool{return $u&&!empty($u['active'])&&$u['role']==='admin';}
/** Student attendance and assessment are separate from tutor QR attendance. */
function acReady():bool{try{q('SELECT id FROM academic_records LIMIT 1');q('SELECT id FROM academic_reassessment_windows LIMIT 1');q('SELECT cohort_key FROM academic_cohorts LIMIT 1');return true;}catch(Throwable $e){return false;}}
function acTutor(?array $u):bool{return $u&&!empty($u['active'])&&(in_array($u['role'],['faculty','hod','pl','daa','admin'],true)||(attReady()&&(bool)one('SELECT user_id FROM tutor_permissions WHERE user_id=? AND enabled=1',[$u['id']])));}
function acReviewer(?array $u):bool{return $u&&!empty($u['active'])&&in_array($u['role'],['pl','daa','admin'],true);}
function acReportViewer(?array $u):bool{return acReviewer($u)||($u&&!empty($u['active'])&&$u['role']==='exam');}
function acWindowManager(?array $u):bool{return $u&&!empty($u['active'])&&in_array($u['role'],['admin','exam'],true);}
function acAccess(?array $u):bool{return acTutor($u)||acReviewer($u)||acWindowManager($u);}
function accountLogin(array $u):bool{return officialLogin($u)||(acReady()&&acTutor($u))||researchStudent($u)||(!empty($u['active'])&&$u['role']==='student');}
function acCanReview(array $u,array $r):bool{if($r['kind']==='attendance')return saReviewer($u);return acReviewer($u)&&($u['role']!=='pl'||($u['department']!==''&&$u['department']===$r['department']));}
function acCanRead(array $u,array $r):bool{if(acAdmin($u))return true;return $r['status']==='Draft'?acTutor($u)&&(int)$r['owner_id']===(int)$u['id']:acCanReview($u,$r);}
function acAssert(bool $ok,string $message):void{if(!$ok)throw new RuntimeException($message);}
function acJson(mixed $v):string{return json_encode($v,JSON_THROW_ON_ERROR|JSON_UNESCAPED_UNICODE);}
function acDecode(string $v):array{return json_decode($v,true,512,JSON_THROW_ON_ERROR);}
function acAudit(array $u,int $id,string $action,array $details=[]):void{q('INSERT INTO academic_audit(record_id,actor_id,action,details,created_at) VALUES(?,?,?,?,?)',[$id,$u['id'],$action,acJson($details),now()]);}
function acKinds():array{return ['attendance'=>'Student attendance','assessment'=>'CA & semester marks','reassessment'=>'Re-assessment'];}
function acPeriods():array{return ['08:00-09:00','09:00-10:00','10:15-11:15','11:15-12:15','13:15-14:15','14:15-15:15','15:30-16:30','16:30-17:30'];}
function acNumber(mixed $v,string $label,float $min=0,float $max=100000):float{acAssert(is_scalar($v)&&is_numeric($v)&&is_finite((float)$v)&&(float)$v>=$min&&(float)$v<=$max,$label.' must be a number between '.$min.' and '.$max.'.');return (float)$v;}
function acText(array $p,string $key,int $max=190):string{$v=required($p,$key);acAssert(mb_strlen($v)<=$max,str_replace('_',' ',$key).' is too long.');return $v;}
function acMetadata(array $p):array{
 if(($p['kind']??'')==='reassessment'){
  $original=one("SELECT * FROM academic_records WHERE id=? AND kind='assessment' AND status='Submitted'".(db()->getAttribute(PDO::ATTR_DRIVER_NAME)==='mysql'?' FOR UPDATE':''),[(int)($p['original_id']??0)]);acAssert((bool)$original,'Select your original submitted assessment.');$original=acHydrate($original);acAssert($original['metadata']['has_exam'],'This module has no ESE. A CA-only re-assessment policy is required before it can use this exam re-sit workflow.');
  $r=array_intersect_key($original,array_flip(['department','programme','academic_year','study_year','semester','section','module_code','module_name','contact_hours']));$r['kind']='reassessment';$r['metadata']=$original['metadata'];$r['metadata']['original_id']=(int)$original['id'];$r['metadata']['window_id']=(int)($p['window_id']??0);$r['metadata']['attempt']='Window #'.$r['metadata']['window_id'];$r['metadata']['review_note']='Original CA retained; new ESE raw mark. A successful re-assessment is capped at 50.';$r['identity_key']=hash('sha256','reassessment|'.$original['id'].'|'.$r['metadata']['window_id']);return $r;
 }
 $r=[];foreach(['kind','department','programme','academic_year','study_year','semester','section','module_code','module_name']as $key)$r[$key]=acText($p,$key);
 acAssert(isset(acKinds()[$r['kind']]),'Choose attendance, assessment or re-assessment.');
 acAssert(examProgrammeDepartment($r['programme'])===$r['department'],'Choose a programme belonging to the selected department.');
 acAssert(preg_match('/^(20\d{2})-(20\d{2})$/',$r['academic_year'],$m)===1&&(int)$m[2]===(int)$m[1]+1,'Academic year must be consecutive years, e.g. 2026-2027.');
 acAssert(in_array($r['study_year'],['I','II','III','IV'],true)&&in_array($r['semester'],['I','II'],true),'Choose Year I–IV and Semester I–II.');
 acAssert(preg_match('/^[A-Z0-9]{1,12}$/',$r['section'])===1,'Use a section such as A.');$r['module_code']=strtoupper($r['module_code']);acAssert(preg_match('/^[A-Z0-9][A-Z0-9 -]{0,39}$/',$r['module_code'])===1,'Use a module code of at most 40 letters, numbers, spaces or hyphens.');
 $r['contact_hours']=acNumber($p['contact_hours']??'','DPD contact hours',0.01,2000);
 $meta=['classroom'=>acText($p,'classroom',100),'credits'=>12];
 if($r['kind']!=='attendance'){
  $components=$p['components']??[];if(is_string($components))$components=acDecode($components);
  acAssert(is_array($components)&&count($components)>=1&&count($components)<=20,'Add 1–20 assessment components.');$names=[];$sum=0;$ese=0;$ca=0;$meta['components']=[];
  foreach($components as $i=>$c){acAssert(is_array($c),'Invalid component.');$name=acText($c,'name',80);$type=$c['type']??'CA';acAssert(in_array($type,['CA','ESE'],true),'Component type must be CA or ESE.');acAssert(!isset($names[mb_strtolower($name)]),'Use different names for each component.');acAssert(!in_array($name,['Student ID','Student Name'],true),'Component names cannot be Student ID or Student Name.');$names[mb_strtolower($name)]=true;$max=acNumber($c['max']??'','Maximum marks',0.01,10000);$weight=acNumber($c['weight']??'','Weight (%)',0.01,100);$sum+=$weight;$type==='ESE'?$ese++:$ca++;$meta['components'][]=['name'=>$name,'type'=>$type,'max'=>$max,'weight'=>$weight];}
  acAssert(abs($sum-100)<0.00001,'CA and ESE weights together must equal exactly 100%.');acAssert($ca>0&&$ese<=1,'Include CA components and at most one End Semester Examination component.');
  $meta['has_exam']=($p['has_exam']??'No')==='Yes';acAssert($ese===($meta['has_exam']?1:0),'The Semester exam selection must match the ESE component.');
 }
 $r['metadata']=$meta;$r['identity_key']=hash('sha256',acJson(array_map(fn($k)=>$r[$k],['kind','programme','academic_year','study_year','semester','section','module_code'])).($meta['attempt']??''));return $r;
}
function acHeaders(array $r):array{if($r['kind']==='reassessment')return ['Student ID','Student Name','Re-exam raw mark'];return $r['kind']==='attendance'?['Date','Student ID','Student Name','Classroom','Class Type',...acPeriods()]:['Student ID','Student Name',...array_column($r['metadata']['components'],'name')];}
function acDate(string $s):string{if(dateValid($s))return $s;if(preg_match('/^(\d{2})-(\d{2})-(\d{4})$/',$s,$m)&&dateValid($m[3].'-'.$m[2].'-'.$m[1]))return $m[3].'-'.$m[2].'-'.$m[1];throw new RuntimeException('Use a valid date YYYY-MM-DD or DD-MM-YYYY.');}
/** Import is all-or-nothing. Errors include row numbers; existing drafts remain intact. */
function acParseRows(array $r,array $rows):array{
 acAssert(count($rows)<=5001,'Upload at most 5,000 rows.');$headers=array_map(fn($v)=>trim(ltrim((string)$v,"\xEF\xBB\xBF")),array_shift($rows)??[]);$needed=acHeaders($r);acAssert(count($headers)===count(array_unique($headers)),'Duplicate column headings.');foreach($needed as $h)acAssert(in_array($h,$headers,true),'Missing column: '.$h.'. Download this module’s template.');
 $entries=[];$seen=[];$names=[];
 foreach($rows as $n=>$row){if(!array_filter($row,fn($v)=>trim((string)$v)!==''))continue;
  try{$data=array_combine($headers,array_slice(array_pad($row,count($headers),''),0,count($headers)));$id=acText($data,'Student ID',60);acAssert(preg_match('/^[\pL\pN][\pL\pN._\/-]*$/u',$id)===1,'Student ID must contain letters/numbers, not spaces.');$name=acText($data,'Student Name',160);acAssert(!isset($names[$id])||$names[$id]===$name,'The same Student ID has different names.');$names[$id]=$name;$v=['student_id'=>$id,'student_name'=>$name];
   if($r['kind']==='attendance'){$v['date']=acDate(trim($data['Date']));acAssert($v['date']<=date('Y-m-d'),'Attendance cannot be recorded for a future date.');[$a,$b]=explode('-',$r['academic_year']);acAssert($v['date']>=$a.'-01-01'&&$v['date']<=$b.'-12-31','Date falls outside the academic year.');$v['classroom']=trim($data['Classroom'])?:$r['metadata']['classroom'];acAssert(mb_strlen($v['classroom'])<=100,'Classroom is too long.');$v['class_type']=trim($data['Class Type']);acAssert(in_array($v['class_type'],['Regular','Extra'],true),'Class Type must be Regular or Extra.');$v['periods']=[];foreach(acPeriods()as $h){$s=strtoupper(trim($data[$h]));acAssert(in_array($s,['','P','A'],true),$h.': use P, A, or blank for an unused period.');$v['periods'][$h]=$s;}acAssert((bool)array_filter($v['periods']),'Enter at least one P or A for this row.');$key=$id.'|'.$v['date'].'|'.$v['class_type'];
   }elseif($r['kind']==='reassessment'){$original=acHydrate(one('SELECT * FROM academic_records WHERE id=?',[$r['metadata']['original_id']]));$student=null;foreach($original['entries']as $ov)if($ov['student_id']===$id)$student=$ov;acAssert((bool)$student,'Student ID is not in the original assessment.');acAssert($student['student_name']===$name,'Student name must match the original assessment.');$eligibility=acEligibility($original,$id);acAssert($eligibility['eligible']&&acMarks($original,$student)['result']==='Fail',$eligibility['message']);$v['marks']=$student['marks'];foreach($r['metadata']['components']as $i=>$c)if($c['type']==='ESE')$v['marks'][$i]=trim((string)$data['Re-exam raw mark'])===''?null:acNumber($data['Re-exam raw mark'],'Re-exam raw mark',0,$c['max']);}else{$v['marks']=[];foreach($r['metadata']['components']as $c){$raw=trim((string)$data[$c['name']]);$v['marks'][]=$raw===''?null:acNumber($raw,$c['name'],0,(float)$c['max']);}$key=$id;}
   if($r['kind']==='reassessment')$key=$id;acAssert(!isset($seen[$key]),'Duplicate student row for this date/type or marks sheet.');$seen[$key]=true;$entries[]=$v;
  }catch(RuntimeException $e){throw new RuntimeException('Row '.($n+2).': '.$e->getMessage());}
 }
 acAssert((bool)$entries,'No student records found.');acValidateEntries($r,$entries,false);return $entries;
}
function acValidateEntries(array $r,array $entries,bool $final):void{
 acAssert(count($entries)<=5000,'Maximum 5,000 rows per module.');if($final)acAssert((bool)$entries,'Add student records before final submission.');
 if($r['kind']==='attendance'){
  $occupied=[];$names=[];$sessions=[];$roster=[];
  foreach($entries as $v){$id=$v['student_id'];acAssert(!isset($names[$id])||$names[$id]===$v['student_name'],'Student ID '.$id.' has inconsistent names.');$names[$id]=$v['student_name'];$roster[$id]=true;foreach($v['periods']as $period=>$status)if($status!==''){$key=$v['date'].'|'.$period;$person=$key.'|'.$id;acAssert(!isset($occupied[$person]),'Overlapping Regular/Extra class for '.$id.' on '.$v['date'].' '.$period.'.');$occupied[$person]=true;if(isset($sessions[$key]))acAssert($sessions[$key]['class_type']===$v['class_type']&&$sessions[$key]['classroom']===$v['classroom'],'All students must use the same class type and classroom for '.$key.'.');else $sessions[$key]=['class_type'=>$v['class_type'],'classroom'=>$v['classroom'],'students'=>[]];$sessions[$key]['students'][$id]=true;}}
  if($final)foreach($sessions as $key=>$session)acAssert(count($session['students'])===count($roster),'Incomplete attendance for '.$key.'. Every student in this module needs P or A for each recorded period; blanks only mean no class.');
 }elseif($final)foreach($entries as $v)acAssert(!in_array(null,$v['marks'],true),'Complete all component marks for '.$v['student_name'].'. Blank marks are not zero.');
}
function acHydrate(array $r):array{$r['metadata']=acDecode($r['metadata']);$r['entries']=acDecode($r['entries']);return $r;}
function acGet(array $u,int $id):array{$r=one('SELECT * FROM academic_records WHERE id=?',[$id]);acAssert($r&&acCanRead($u,$r),'This record is not available to your account. Submitted work is visible only to authorised reviewers.');$r=acHydrate($r);return $r;}
function acMerge(array $r,array $old,array $new):array{if($r['kind']==='attendance')return saMerge($r,$old,$new,false);$map=[];foreach([...$old,...$new]as $v){$key=$v['student_id'].($r['kind']==='attendance'?'|'.$v['date'].'|'.$v['class_type']:'');$map[$key]=$v;}return array_values($map);}
function acPost(?array $u,string $action,array $p):int{
 acAssert(acReady()&&acAccess($u),'Sign in with an active teaching or academic review account.');db()->beginTransaction();
 try{
  if($action==='ac_cohort_save'){acAssert(acWindowManager($u),'Only Exam Cell/Admin can configure expected modules.');acSaveCohort($u,$p);$id=0;}elseif(in_array($action,['ac_window_create','ac_window_toggle'],true)){acAssert(acWindowManager($u),'Only Exam Cell or Admin can manage re-assessment entry windows.');if($action==='ac_window_create'){$year=acText($p,'academic_year',20);acAssert(preg_match('/^(20\d{2})-(20\d{2})$/',$year,$ym)===1&&(int)$ym[2]===(int)$ym[1]+1,'Use an academic year such as 2026-2027.');$semester=acText($p,'semester',4);acAssert(in_array($semester,['I','II'],true),'Select Semester I or II.');$prog=trim($p['programme']??'');acAssert($prog===''||in_array($prog,examProgrammes(),true),'Invalid programme.');$start=str_replace('T',' ',acText($p,'opens_at',20));$end=str_replace('T',' ',acText($p,'closes_at',20));acAssert(acDateTimeValid($start)&&acDateTimeValid($end)&&$end>$start,'Choose valid opening and closing times, with closing after opening.');q('INSERT INTO academic_reassessment_windows(title,academic_year,semester,programme,opens_at,closes_at,created_by,created_at) VALUES(?,?,?,?,?,?,?,?)',[acText($p,'title'),$year,$semester,$prog,$start.':00',$end.':00',$u['id'],now()]);acAudit($u,0,'Re-assessment window created',['window_id'=>(int)db()->lastInsertId(),'opens'=>$start,'closes'=>$end]);}else{$wid=(int)($p['window_id']??0);$enabled=($p['enabled']??'0')==='1'?1:0;acAssert((bool)one('SELECT id FROM academic_reassessment_windows WHERE id=?',[$wid]),'Window not found.');q('UPDATE academic_reassessment_windows SET enabled=? WHERE id=?',[$enabled,$wid]);acAudit($u,0,'Re-assessment window changed',['window_id'=>$wid,'enabled'=>$enabled]);}$id=0;}elseif($action==='ac_create'){
   acAssert(acTutor($u),'Only teaching staff can create their own module records.');$r=acMetadata($p);if($r['kind']==='attendance'&&!acAdmin($u))saWindow($r,(int)($p['window_id']??0),true);if($r['kind']==='reassessment'){$original=one('SELECT owner_id FROM academic_records WHERE id=?',[$r['metadata']['original_id']]);acAssert(acAdmin($u)||(int)$original['owner_id']===(int)$u['id'],'Only the original tutor can create this re-assessment.');acAssert(acAdmin($u)||acWindowOpen($r,true),'No matching re-assessment entry window is open.');}
   acAssert(!one('SELECT id FROM academic_records WHERE identity_key=?',[$r['identity_key']]),'This module/cohort already has a record of this type. Open your existing draft or contact PL/DAA.');
   q('INSERT INTO academic_records(owner_id,kind,identity_key,department,programme,academic_year,study_year,semester,section,module_code,module_name,contact_hours,metadata,entries,created_at,updated_at) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)',[$u['id'],$r['kind'],$r['identity_key'],$r['department'],$r['programme'],$r['academic_year'],$r['study_year'],$r['semester'],$r['section'],$r['module_code'],$r['module_name'],$r['contact_hours'],acJson($r['metadata']),'[]',now(),now()]);$id=(int)db()->lastInsertId();acAudit($u,$id,'Draft created');
  }else{
   $id=(int)($p['id']??0);$raw=one('SELECT * FROM academic_records WHERE id=?'.(db()->getAttribute(PDO::ATTR_DRIVER_NAME)==='mysql'?' FOR UPDATE':''),[$id]);acAssert((bool)$raw,'Record not found.');$r=acHydrate($raw);acAssert((int)($p['revision']??0)===(int)$r['revision'],'This record changed in another window. Reload before saving.');
   if($r['kind']==='attendance'&&!acAdmin($u))saWindow($r,(int)($p['window_id']??0),true);
   if($action==='ac_admin_delete'){
    acAssert(acAdmin($u),'Only Admin can delete academic records.');$reason=acText($p,'reason',1000);acAssert(($p['confirmed']??'')==='1','Confirm deletion of this record.');
    if($r['kind']==='assessment'){$linked=[];foreach(all("SELECT id,metadata FROM academic_records WHERE kind='reassessment'")as $candidate)if((int)(acDecode($candidate['metadata'])['original_id']??0)===$id)$linked[]='#'.$candidate['id'];acAssert(!$linked,'Delete linked re-assessment records first: '.implode(', ',$linked).'.');}
    $snapshot=['record'=>$r,'reason'=>$reason];if($r['kind']==='attendance')$snapshot['verifications']=all('SELECT * FROM student_attendance_verifications WHERE record_id=?',[$id]);
    acAudit($u,$id,'Administrator deleted academic record',$snapshot);
    if($r['kind']==='attendance')q('DELETE FROM student_attendance_verifications WHERE record_id=?',[$id]);
    q('DELETE FROM academic_records WHERE id=?',[$id]);$id=0;
   }elseif($action==='ac_admin_correct'){
    acAssert(acAdmin($u)&&$r['status']==='Submitted'&&$r['kind']!=='attendance','Administrator access to a submitted marks record is required.');$reason=acText($p,'reason',1000);$f=$_FILES['sheet']??[];acAssert(($f['error']??1)===UPLOAD_ERR_OK&&$f['size']<=10*1024*1024&&is_uploaded_file($f['tmp_name']),'Choose a CSV or XLSX up to 10 MB.');acAssert(in_array(strtolower(pathinfo($f['name'],PATHINFO_EXTENSION)),['csv','xlsx'],true),'Choose CSV or XLSX.');$entries=acParseRows($r,workbookRows($f['tmp_name'],$f['name']));acValidateEntries($r,$entries,true);q('UPDATE academic_records SET entries=?,revision=revision+1,updated_at=? WHERE id=?',[acJson($entries),now(),$id]);acAudit($u,$id,'Administrator corrected submitted marks',['before'=>$r['entries'],'after'=>$entries,'reason'=>$reason]);
   }elseif($action==='ac_contact_hours'){
    acAssert($u['role']==='admin'&&$r['kind']!=='attendance'&&$r['status']==='Submitted','Only an administrator can correct submitted DPD contact hours.');$hours=acNumber($p['contact_hours']??'','DPD contact hours',0.01,2000);$reason=acText($p,'reason',1000);q('UPDATE academic_records SET contact_hours=?,revision=revision+1,updated_at=? WHERE id=?',[$hours,now(),$id]);acAudit($u,$id,'Contact hours corrected',['old'=>$r['contact_hours'],'new'=>$hours,'reason'=>$reason]);
   }else{
    acAssert((acAdmin($u)||(acTutor($u)&&(int)$r['owner_id']===(int)$u['id']))&&$r['status']==='Draft','Only the owner can edit a draft. Submitted records are locked.');
    if($r['kind']==='reassessment')acAssert(acAdmin($u)||acWindowOpen($r,true),'Re-assessment entry is closed. Your saved draft remains available.');
    if($action==='ac_submit'){if($r['kind']==='reassessment')acParseRows($r,[acHeaders($r),...acSheetRows($r)]);acAssert(($p['confirmed']??'')==='1','Confirm that the entries and DPD contact hours have been checked.');acValidateEntries($r,$r['entries'],true);q("UPDATE academic_records SET status='Submitted',submitted_at=?,updated_at=?,revision=revision+1 WHERE id=?",[now(),now(),$id]);acAudit($u,$id,'Final submission',['rows'=>count($r['entries'])]);}
    elseif($action==='ac_discard'){q('DELETE FROM academic_records WHERE id=?',[$id]);acAudit($u,$id,'Empty / mistaken draft discarded');$id=0;}
    elseif($action==='ac_save_metadata'){$p['kind']=$r['kind'];$new=acMetadata($p);if($new['kind']==='attendance'&&!acAdmin($u))saWindow($new,(int)($p['window_id']??0),true);if($r['entries']){acAssert($r['kind']==='attendance'||count($new['metadata']['components'])===count($r['metadata']['components']),'With uploaded marks, keep the same number/order of components. Create a corrected draft if the structure changes.');$checked=acParseRows($new,[acHeaders($new),...acSheetRows($r)]);}acAssert(!one('SELECT id FROM academic_records WHERE identity_key=? AND id<>?',[$new['identity_key'],$id]),'This module/cohort already exists.');if($r['kind']==='reassessment')acAssert($new['metadata']['original_id']===$r['metadata']['original_id'],'Original assessment cannot be changed.');q('UPDATE academic_records SET identity_key=?,department=?,programme=?,academic_year=?,study_year=?,semester=?,section=?,module_code=?,module_name=?,contact_hours=?,metadata=?,revision=revision+1,updated_at=? WHERE id=?',[$new['identity_key'],$new['department'],$new['programme'],$new['academic_year'],$new['study_year'],$new['semester'],$new['section'],$new['module_code'],$new['module_name'],$new['contact_hours'],acJson($new['metadata']),now(),$id]);acAudit($u,$id,'Draft configuration changed');}
    elseif(in_array($action,['ac_upload','ac_save_rows'],true)){
     if($action==='ac_upload'){$f=$_FILES['sheet']??[];acAssert(($f['error']??1)===UPLOAD_ERR_OK&&$f['size']<=10*1024*1024,'Choose a CSV or XLSX up to 10 MB.');acAssert(in_array(strtolower(pathinfo($f['name'],PATHINFO_EXTENSION)),['csv','xlsx'],true),'Choose CSV or XLSX.');$rows=$r['kind']==='attendance'?saReadFile($f):workbookRows($f['tmp_name'],$f['name']);}else{$rows=acDecode((string)($p['sheet_rows']??''));}
     $entries=$r['kind']==='attendance'?saParseMatrix($r,$rows):acParseRows($r,$rows);if(($p['merge_mode']??'replace')==='merge')$entries=acMerge($r,$r['entries'],$entries);acValidateEntries($r,$entries,false);q('UPDATE academic_records SET entries=?,revision=revision+1,updated_at=? WHERE id=?',[acJson($entries),now(),$id]);acAudit($u,$id,'Draft rows saved',['rows'=>count($entries),'mode'=>$p['merge_mode']??'replace']);
    }else throw new RuntimeException('Unknown Academic action.');
   }
  }db()->commit();return $id;
 }catch(Throwable $e){if(db()->inTransaction())db()->rollBack();throw $e;}
}
function acMarks(array $r,array $v):array{
 $ca=0;$ese=0;$caWeight=0;$eseWeight=0;$complete=true;
 foreach($r['metadata']['components']as $i=>$c){if($c['type']==='CA')$caWeight+=$c['weight'];else $eseWeight+=$c['weight'];$mark=$v['marks'][$i];if($mark===null){$complete=false;continue;}$weighted=$mark/$c['max']*$c['weight'];if($c['type']==='CA')$ca+=$weighted;else $ese+=$weighted;}
 $passed=$complete&&$ca+0.0000001>=$caWeight*.4&&($eseWeight===0||$ese+0.0000001>=$eseWeight*.4)&&$ca+$ese+0.0000001>=50;
 $raw=$complete?round($ca+$ese,2):null;$result=$complete?($passed?'Pass':'Fail'):'Incomplete';
 return ['ca'=>round($ca,2),'ese'=>$r['metadata']['has_exam']?round($ese,2):null,'raw_total'=>$raw,'total'=>$r['kind']==='reassessment'&&$passed?50.0:$raw,'result'=>$result,'ca_pass'=>$ca+0.0000001>=$caWeight*.4,'ese_pass'=>$eseWeight===0||$ese+0.0000001>=$eseWeight*.4];
}
function acRecordedPercent(array $student):?float { return $student['recorded']>0?100*$student['present']/$student['recorded']:null; }
function acAttendance(array $r):array{
 $students=[];$sessions=[];foreach($r['entries']as $v){$id=$v['student_id'];$students[$id]??=['id'=>$id,'name'=>$v['student_name'],'present'=>0,'absent'=>0,'extra_present'=>0,'recorded'=>0];foreach($v['periods']as $period=>$status)if($status!==''){$sessions[$v['date'].'|'.$period]=$v['class_type'];$students[$id]['recorded']++;if($status==='P'){$students[$id]['present']++;if($v['class_type']==='Extra')$students[$id]['extra_present']++;}else $students[$id]['absent']++;}}
 foreach($students as &$s){$s['recorded_percentage']=$s['recorded']?round(100*$s['present']/$s['recorded'],2):null;$s['dpd_progress']=round(100*$s['present']/(float)$r['contact_hours'],2);$s['percentage']=floor(min(100,100*$s['present']/(float)$r['contact_hours'])*100)/100;$s['flag']=$s['recorded_percentage']===null?'No data':(acRecordedPercent($s)<80?'Not allowed to sit the exam':(acRecordedPercent($s)<90?'Supporting document and verification required':'Allowed to sit the exam'));}unset($s);
 return ['students'=>array_values($students),'hours'=>count($sessions),'extra_hours'=>count(array_filter($sessions,fn($s)=>$s==='Extra')),'complete'=>count($sessions)>=(float)$r['contact_hours']];
}
function acReportRecords(array $u,array $filters):array{
 acAssert(acReportViewer($u),'Exam Cell, PL, DAA or administrator access required.');$sql="SELECT r.*,u.name AS tutor_name FROM academic_records r JOIN users u ON u.id=r.owner_id WHERE r.status='Submitted'";$params=[];if(!saReviewer($u))$sql.=" AND r.kind<>'attendance'";
 if(!empty($filters['_summary_only']))$sql=str_replace('r.*',"r.id,r.owner_id,r.kind,r.department,r.programme,r.academic_year,r.study_year,r.semester,r.section,r.module_code,r.module_name,r.contact_hours,r.metadata,r.status,r.submitted_at,r.updated_at,'[]' AS entries",$sql);
 if($u['role']==='pl'){$sql.=' AND r.department=?';$params[]=$u['department'];}
 foreach(['department','programme','academic_year','study_year','semester','section','kind']as $key)if(($filters[$key]??'')!==''){if($key==='kind'&&$filters[$key]==='assessment')$sql.=" AND r.kind IN ('assessment','reassessment')";else{$sql.=' AND r.'.$key.'=?';$params[]=$filters[$key];}}
 return array_map(function($r)use($u){$r=acHydrate($r);return $r;},all($sql.' ORDER BY r.programme,r.study_year,r.module_code,r.id',$params));
}
function acConsolidate(array $records):array{
 $groups=[];foreach($records as $r){if($r['kind']!=='assessment'||!$r['entries'])continue;$key=implode(' · ',[$r['programme'],'Year '.$r['study_year'],'Semester '.$r['semester'],$r['academic_year'],'Section '.$r['section']]);$groups[$key]['modules'][$r['id']]=$r;foreach($r['entries']as $v){$id=$v['student_id'];$groups[$key]['students'][$id]??=['id'=>$id,'name'=>$v['student_name'],'marks'=>[],'name_conflict'=>false];if($groups[$key]['students'][$id]['name']!==$v['student_name'])$groups[$key]['students'][$id]['name_conflict']=true;$groups[$key]['students'][$id]['marks'][$r['id']]=acMarks($r,$v);}}
 foreach($records as $r){if($r['kind']!=='reassessment')continue;foreach($groups as &$g){$originalId=$r['metadata']['original_id'];if(!isset($g['modules'][$originalId]))continue;foreach($r['entries']as $v){$sid=$v['student_id'];if(!isset($g['students'][$sid]))continue;$old=$g['students'][$sid]['marks'][$originalId];if(($old['reassessment_id']??0)>(int)$r['id'])continue;$new=acMarks($r,$v);$new['reassessment_id']=(int)$r['id'];$g['students'][$sid]['marks'][$originalId]=$new;}}unset($g);}
 foreach($groups as &$g){foreach($g['students']as &$s){$totals=array_column($s['marks'],'total');$s['complete']=count($totals)===count($g['modules'])&&!in_array(null,$totals,true);$s['average']=$s['complete']?round(array_sum($totals)/count($totals),2):null;}unset($s);}unset($g);return $groups;
}

function acDateTimeValid(string $v):bool{$d=DateTimeImmutable::createFromFormat('!Y-m-d H:i',$v);return $d&&$d->format('Y-m-d H:i')===$v;}
function acWindowOpen(array $r,bool $lock=false):bool{
 $sql='SELECT * FROM academic_reassessment_windows WHERE id=?'.($lock&&db()->getAttribute(PDO::ATTR_DRIVER_NAME)==='mysql'?' FOR UPDATE':'');$w=one($sql,[(int)($r['metadata']['window_id']??0)]);
 return $w&&(int)$w['enabled']===1&&$w['opens_at']<=now()&&$w['closes_at']>=now()&&$w['academic_year']===$r['academic_year']&&$w['semester']===$r['semester']&&($w['programme']===''||$w['programme']===$r['programme']);
}

function acCohortKey(array $r):string{return hash('sha256',acJson(array_map(fn($k)=>(string)$r[$k],['programme','academic_year','study_year','semester','section'])));}
function acSaveCohort(array $u,array $p):void{
 $r=acMetadata(array_merge($p,['kind'=>'attendance','department'=>examProgrammeDepartment($p['programme']??''),'module_code'=>'COHORT','module_name'=>'Cohort configuration','contact_hours'=>1,'classroom'=>'Not applicable']));
 $codes=array_values(array_unique(array_filter(array_map(fn($v)=>strtoupper(trim($v)),preg_split('/[,\r\n]+/',acText($p,'module_codes',2000))))));acAssert(count($codes)>0&&count($codes)<=20,'Enter 1–20 expected module codes.');foreach($codes as $code)acAssert(preg_match('/^[A-Z0-9][A-Z0-9 -]{0,39}$/',$code)===1,'Invalid module code: '.$code);$key=acCohortKey($r);
 $old=one('SELECT * FROM academic_cohorts WHERE cohort_key=?',[$key]);if($old)q('UPDATE academic_cohorts SET module_codes=?,updated_by=?,updated_at=? WHERE cohort_key=?',[acJson($codes),$u['id'],now(),$key]);else q('INSERT INTO academic_cohorts(cohort_key,programme,academic_year,study_year,semester,section,module_codes,updated_by,updated_at) VALUES(?,?,?,?,?,?,?,?,?)',[$key,$r['programme'],$r['academic_year'],$r['study_year'],$r['semester'],$r['section'],acJson($codes),$u['id'],now()]);acAudit($u,0,'Expected cohort modules saved',['cohort'=>$key,'before'=>$old?acDecode($old['module_codes']):[],'after'=>$codes]);
}
function acEligibility(array $r,string $studentId):array{
 $cohort=one('SELECT module_codes FROM academic_cohorts WHERE cohort_key=?',[acCohortKey($r)]);if(!$cohort)return ['eligible'=>false,'failed'=>null,'message'=>'Awaiting expected module list from Exam Cell/Admin.'];$expected=acDecode($cohort['module_codes']);$records=all("SELECT * FROM academic_records WHERE kind='assessment' AND status='Submitted' AND programme=? AND academic_year=? AND study_year=? AND semester=? AND section=?",[$r['programme'],$r['academic_year'],$r['study_year'],$r['semester'],$r['section']]);$marks=[];
 foreach($records as $row){$row=acHydrate($row);foreach($row['entries']as $v)if($v['student_id']===$studentId)$marks[$row['module_code']]=acMarks($row,$v);}
 foreach($expected as $code)if(!isset($marks[$code])||$marks[$code]['result']==='Incomplete')return ['eligible'=>false,'failed'=>null,'message'=>'Awaiting original submitted marks for '.$code.'.'];
 if(!in_array($r['module_code'],$expected,true))return ['eligible'=>false,'failed'=>null,'message'=>'Module missing from expected cohort module list.'];$failed=0;foreach($expected as $code)if($marks[$code]['result']==='Fail')$failed++;
 return ['eligible'=>$failed>=1&&$failed<=2,'failed'=>$failed,'message'=>$failed>2?'Repeat semester: '.$failed.' failed modules.':($failed===0?'No re-assessment required.':$failed.' failed module(s): eligible for re-assessment.')];
}

function acDeleteForm(array $u,array $r):void{
 if(!acAdmin($u))return;
 echo '<section class="card"><h2>Administrator: delete this record</h2><p>Remove this module record from active lists, reports and calculations. Use this for dummy or mistaken submissions. A full snapshot and your reason remain in the audit history. This does not delete other modules or the tutor account.</p><form method="post" data-confirm="Delete this academic record from active records and reports?">';csrf();
 echo '<input type="hidden" name="action" value="ac_admin_delete"><input type="hidden" name="id" value="'.(int)$r['id'].'"><input type="hidden" name="revision" value="'.(int)$r['revision'].'"><label>Reason for deletion<input name="reason" required maxlength="1000" placeholder="For example: dummy data used for testing"></label><label class="check"><input type="checkbox" name="confirmed" value="1" required>I confirm deletion of '.e($r['module_code']).' — receipt #'.(int)$r['id'].'.</label><button class="danger-button">Delete record</button></form></section>';
}
